// ZoFHub · ai.js — CLIENT-SIDE AI.
//
// Text + images are generated by calling Pollinations.ai DIRECTLY from the
// browser, so every visitor's request goes out on THEIR OWN IP. That is the fix
// for "the AI cannot respond": previously every request was proxied through our
// single server IP, so under any load the shared anonymous quota was drained and
// requests piled up. Calling from the user's machine spreads the load across all
// visitors and makes the AI effectively unlimited (it's your IP, not ours).
// Pollinations is free + keyless and returns `Access-Control-Allow-Origin: *`,
// so the browser is allowed to call it directly.
//
// There is NO server route anymore. pollinations.js tries several BROWSER-DIRECT
// routes in a row (streaming POST → the simple GET URL API → a warm-up retry),
// all on the visitor's own connection. Only if the device is genuinely OFFLINE
// do we spin up a small in-browser model as a last resort. Nothing AI ever
// touches our server, so the shared-IP rate limit that caused "AI is busy" is gone.

import { $, $$, el, renderMarkdownLite, escapeHtml } from './utils.js';
import { store } from './storage.js';
import { pollTextStream, pollImageUrl, IS_LOCAL } from './pollinations.js?v=20260720';
import { SYSTEM_PROMPT } from './ai-prompt.js';
import { hfAvailable, hfChatStream } from './hf-inference.js';
import { getProvider, puterChatStream, puterImageSrc } from './puter-ai.js';

// ---- Config ---------------------------------------------------------------
// Text + images are generated by calling Pollinations DIRECTLY from the user's
// browser (see pollinations.js) — AI load NEVER hits our server, on any path.
const SYSTEM = SYSTEM_PROMPT;   // see public/js/ai-prompt.js
const MODEL  = 'HuggingFaceTB/SmolLM2-360M-Instruct'; // local in-browser fallback only

let pipelinePromise = null;
let lastAnswerMeta = null;   // { provider, model } for feedback provenance
// When the visitor explicitly chose Puter but it failed and we fell through to
// the free default, this holds the human reason. done() surfaces it at the END
// of the turn — a transient setStatus() here would be overwritten within
// milliseconds by the fallback provider's own status, so the honest "Puter
// didn't answer, the default did" message has to ride through to the finish.
// Without this the swap is silent and Puter looks simply "broken".
let puterFellBack = null;
let current = null;
let composing = false;

const sleep = (ms) => new Promise(r => setTimeout(r, ms));
// Reasoning models occasionally leak a <think> block into content — strip it.
const clean = (s) => String(s || '').replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

(function init() {
  loadHistory();
  $('#aiNew')?.addEventListener('click', newChat);
  $('#aiClearAll')?.addEventListener('click', clearAllChats);
  bindComposer();
  bindSuggestCards($('#aiMessages'));
  setStatus('Online AI ready · free & unlimited · try /image');
})();

function setStatus(text) {
  const s = $('#aiEngineStatus');
  if (s) s.textContent = text;
}

function bindSuggestCards(scope) {
  $$('.ai-suggest-card', scope || document).forEach(c => c.addEventListener('click', () => {
    const p = c.dataset.prompt || c.textContent;
    const i = $('#aiInput'); if (i) { i.value = p; i.focus(); autoSize(i); }
  }));
}

// Bounded chat context sent to the model: our system prompt + the last 8 real
// (non-streaming, non-image) turns.
function buildContext() {
  const history = current.messages
    .filter(m => !m.streaming && m.content && m.kind !== 'image')
    .slice(-8)
    .map(m => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: String(m.content).slice(0, 4000) }));
  return [{ role: 'system', content: SYSTEM }, ...history];
}

// ---- Client-side answer cache (localStorage) --------------------------------
// Before hitting Pollinations, check if we've already answered this exact
// standalone question on THIS device. Hit → instant, zero network. Miss → fetch,
// then store. Bounded so it can't grow forever. Stays entirely on-device (no
// server, no personal data) — matches the "private, local-first" model.
const AI_CACHE_KEY = 'zofhub:ai:cache:v1';
const AI_CACHE_MAX = 200;
const normQ = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
function aiCacheGet(q) {
  if (!q || q.length < 12) return null;                 // skip short/contextual messages
  try { return (JSON.parse(localStorage.getItem(AI_CACHE_KEY) || '{}'))[normQ(q)] || null; }
  catch { return null; }
}
function aiCacheSet(q, answer) {
  if (!q || q.length < 12 || !answer) return;
  try {
    const m = JSON.parse(localStorage.getItem(AI_CACHE_KEY) || '{}');
    m[normQ(q)] = answer;
    const keys = Object.keys(m);
    if (keys.length > AI_CACHE_MAX) delete m[keys[0]];  // evict oldest to stay bounded
    localStorage.setItem(AI_CACHE_KEY, JSON.stringify(m));
  } catch { /* storage full/blocked → just skip caching */ }
}

async function respond() {
  composing = true;
  setSendBusy(true);

  const userMsg = (current.messages.filter(m => m.role === 'user').slice(-1)[0]?.content || '').trim();

  // ----- Slash command: /image (fully client-side) -----
  const imageMatch = userMsg.match(/^\/(?:image|img|draw)\s+([\s\S]+)/i);
  if (imageMatch) { await handleImage(imageMatch[1].trim()); finishTurn(); return; }

  // ----- Normal text chat -----
  const reply = { role: 'assistant', content: '', streaming: true };
  current.messages.push(reply);
  render();
  puterFellBack = null;   // fresh each turn, so a stale note can't leak forward

  const messages = buildContext();

  // 0) Instant answer from THIS DEVICE's cache — if we've answered this exact
  //    standalone question before, show it with zero network calls. Only for a
  //    first/standalone turn (follow-ups depend on context, so never cache-serve).
  const userTurns = current.messages.filter(m => m.role === 'user').length;
  const cachedAnswer = userTurns <= 1 ? aiCacheGet(userMsg) : null;
  if (cachedAnswer) { setStatus('Answered instantly from this device'); return done(reply, cachedAnswer, false); }

  // Which provider did the visitor choose in AI settings? Default 'auto' —
  // nothing is forced. An explicit choice is honoured FIRST; on any failure the
  // free default chain below still runs, so a choice can never hard-fail the AI.
  const provider = getProvider();

  // 0.5) PUTER — only when explicitly chosen. Runs browser-direct and is billed
  //      to the visitor's own Puter account (their first message opens Puter's
  //      sign-in). It never touches our server. On failure we fall through.
  if (provider === 'puter') {
    try {
      const { text, model } = await puterChatStream(messages, {
        onStatus: setStatus,
        onToken: (partial) => { reply.content = partial; reply.streaming = true; render(); },
      });
      if (userTurns <= 1) aiCacheSet(userMsg, text);
      lastAnswerMeta = { provider: 'puter', model };
      return done(reply, text, false);
    } catch (e) {
      const why = String(e?.message || e);
      if (why === 'aborted') return;
      // Record WHY, in words the visitor can act on, and let the default chain
      // below answer. done() shows this so the fallback is never silent.
      puterFellBack =
        why === 'puter-sdk-blocked' ? 'Puter is blocked on this network'
        : why === 'puter-empty'     ? 'Puter returned an empty reply'
        : 'Puter didn’t complete — its sign-in may have been dismissed, or the account is out of credits';
      console.warn('[ai] Puter unavailable, falling back:', why);
    }
  }

  // 1) HUGGING FACE, only when the user opted in with their own token — and only
  //    in 'auto'/'huggingface' modes, so an explicit Pollinations or Puter
  //    choice never silently spends that token.
  //
  //    Order is evidence-based, not preference. Measured over twelve sequential
  //    attempts from a production origin, the Pollinations streaming path
  //    returned an EMPTY stream 6 times out of 12, and the surviving fallback
  //    answered with a median of 32.5s. Hugging Face routes across several
  //    independent providers, so it is the better first choice for anyone who
  //    has configured it — and somebody who went and pasted a token plainly
  //    expects it to be used, not held in reserve.
  //
  //    Nothing changes for the default visitor: with no token this is a
  //    synchronous false and the original path runs untouched.
  if (hfAvailable() && (provider === 'auto' || provider === 'huggingface')) {
    try {
      const { text, model } = await hfChatStream(messages, {
        onStatus: setStatus,
        onToken: (partial) => { reply.content = partial; reply.streaming = true; render(); },
      });
      if (userTurns <= 1) aiCacheSet(userMsg, text);
      lastAnswerMeta = { provider: 'huggingface', model };
      return done(reply, text, false);
    } catch (e) {
      const why = String(e?.message || e);
      if (why === 'aborted') return;
      // A bad token is worth SAYING, once. Silently falling through would leave
      // someone staring at a settings field they believe is working.
      if (why === 'hf-auth') {
        setStatus('That Hugging Face token was rejected — check it in AI settings.');
      }
      console.warn('[ai] Hugging Face unavailable, falling back:', why);
    }
  }

  // 2) pollTextStream calls Pollinations DIRECTLY from this device and STREAMS the
  //    reply token-by-token (first words show in ~1-2s). It retries across several
  //    BROWSER-DIRECT routes (no server) before giving up. onToken renders live.
  try {
    const { text } = await pollTextStream(messages, {
      onStatus: setStatus,
      onToken: (partial) => { reply.content = partial; reply.streaming = true; render(); },
    });
    if (userTurns <= 1) aiCacheSet(userMsg, text);       // remember standalone Q→A for instant repeats
    return done(reply, text, false);
  } catch (e) {
    console.warn('[ai] online AI unavailable:', e?.message || e);
    // A genuine RATE LIMIT (429) gets its OWN styled notice + live countdown —
    // we do NOT silently download the heavy on-device model for a temporary
    // throttle. Drop the empty streaming bubble so the notice stands alone.
    if (e?.rateLimited) {
      if (current.messages[current.messages.length - 1] === reply) current.messages.pop();
      render();
      showRateLimit(e.retryAfter || 15);
      finishTurn();
      return;
    }
  }

  // 3) NON-rate-limit failure (offline / network / Pollinations down): fall back
  //    to the GUARANTEED-FREE on-device model so the AI NEVER hard-fails.
  if (await localFallback(reply)) return;

  reply.content = '_That reply didn’t come through — just hit send once more and it will._';
  reply.streaming = false; render();
  setStatus('Tap send to retry');
  finishTurn();
}

// Run the on-device model (Transformers.js) into `reply`. One-time ~download,
// then cached; returns true if it produced a usable answer.
async function localFallback(reply) {
  try {
    setStatus('Switching to the on-device AI (one-time setup)…');
    await localGenerate(buildContext(), reply);
    if (reply.content && reply.content !== '(no response)') { done(reply, reply.content, true); return true; }
  } catch (e) { console.error('[ai] on-device engine failed:', e?.message || e); }
  return false;
}

// Answer the last user message with the on-device model on demand (the "Use
// offline AI" button in the rate-limit notice — the truly-unlimited path).
async function useOfflineForLast() {
  const reply = { role: 'assistant', content: '', streaming: true };
  current.messages.push(reply);
  render();
  if (await localFallback(reply)) return;
  reply.content = '_The on-device AI couldn’t start here — hit send to try the online AI again._';
  reply.streaming = false; render();
  finishTurn();
}

// ── Styled "you hit the rate limit" notice ─────────────────────────────────
// Shown ONLY on a genuine 429. A calm amber card (not a red error) with a live
// countdown, a Retry button that arms when the window clears, and an "offline AI"
// escape hatch. Not stored in chat history — it's transient UI. Locks the
// composer for the countdown so an instant resend can't immediately re-trip 429.
function showRateLimit(seconds) {
  const wrap = $('#aiMessages'); if (!wrap) return;
  wrap.querySelector('.ai-ratelimit-row')?.remove();   // only ever one at a time
  const total = Math.max(5, Math.min(120, Math.round(seconds) || 15));

  aiCooling = true; setSendBusy(true);

  const row = el('div', { class: 'msg assistant ai-ratelimit-row' });
  row.innerHTML = `
    <div class="msg-av">AI</div>
    <div class="msg-body">
      <div class="ai-ratelimit" role="status" aria-live="polite">
        <span class="ai-rl-icon" aria-hidden="true">
          <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2h12M6 22h12M6 2v5a6 6 0 0 0 6 6 6 6 0 0 0 6-6V2M6 22v-5a6 6 0 0 1 6-6 6 6 0 0 1 6 6v5"/></svg>
        </span>
        <div class="ai-rl-text">
          <b>You've reached the AI's rate limit</b>
          <span>The free AI is shared and only allows a few messages in a short window. It'll be ready again in <b class="ai-rl-count">${total}s</b>.</span>
        </div>
        <div class="ai-rl-actions">
          <button class="ai-rl-btn ai-rl-retry" type="button" disabled>Retry in ${total}s</button>
          <button class="ai-rl-btn ai-rl-local" type="button">Use offline AI</button>
        </div>
      </div>
    </div>`;
  wrap.appendChild(row);
  wrap.scrollTop = wrap.scrollHeight;

  const countEl = row.querySelector('.ai-rl-count');
  const retryBtn = row.querySelector('.ai-rl-retry');
  let left = total;
  const arm = () => {
    if (countEl) countEl.textContent = 'now';
    retryBtn.disabled = false;
    retryBtn.textContent = 'Retry now';
    retryBtn.classList.add('ready');
    aiCooling = false; setSendBusy(composing);
  };
  const tick = setInterval(() => {
    left -= 1;
    if (left <= 0) { clearInterval(tick); arm(); }
    else { if (countEl) countEl.textContent = left + 's'; retryBtn.textContent = `Retry in ${left}s`; }
  }, 1000);

  retryBtn.addEventListener('click', () => {
    if (retryBtn.disabled) return;
    clearInterval(tick);
    row.remove();
    respond();
  });
  row.querySelector('.ai-rl-local').addEventListener('click', () => {
    clearInterval(tick); arm();     // unlock the composer
    row.remove();
    useOfflineForLast();
  });
}

function done(reply, txt, local) {
  reply.content = txt; reply.streaming = false; render();
  if (puterFellBack) {
    // The visitor picked Puter, it failed, and one of the free providers
    // answered instead. Say so plainly rather than passing the answer off as
    // Puter's — surfacing the real cause, not a generic "ready".
    setStatus(`${puterFellBack} — answered with the default AI instead.`);
    puterFellBack = null;
  } else {
    setStatus(local ? 'Local engine ready' : 'Online AI ready · free & unlimited · try /image');
  }
  finishTurn();
}

// ----- /image <prompt> — generate via the Pollinations WEB URL, browser-direct.
// Image generation takes ~5-30s, so we show a live "Generating…" spinner and only
// swap in the picture once its bytes have actually decoded (no blank/broken-icon
// flash). PRIMARY route is the keyless web URL (image.pollinations.ai/prompt/…)
// straight from this device; if that fails or is blocked on the visitor's network,
// we fall back ONCE to the same-origin /api/ai/image route so an image still comes
// through. On total failure we show a clear, retryable message — never a silent blank.
async function handleImage(prompt) {
  const seed = Math.floor(Math.random() * 1e6);
  const reply = { role: 'assistant', content: prompt, kind: 'image', imageState: 'loading', streaming: false };
  current.messages.push(reply);
  render();
  setStatus('Generating image…');

  // Puter first when chosen (txt2img, billed to the visitor's own Puter
  // account). Any failure falls through to the free Pollinations route below.
  if (getProvider() === 'puter') {
    try {
      reply.imageUrl = await preloadImage(await puterImageSrc(prompt), 60000);
      reply.imageState = 'done';
      render();
      setStatus('Online AI ready · free & unlimited · try /image');
      return;
    } catch (e0) {
      console.warn('[ai] Puter image failed; using the default route:', e0?.message || e0);
    }
  }

  const directUrl = pollImageUrl(prompt, seed);                                          // web URL, browser-direct (primary)
  const serverUrl = `/api/ai/image?prompt=${encodeURIComponent(prompt.slice(0, 1000))}&seed=${seed}`; // same-origin fallback

  try {
    let url;
    try {
      url = await preloadImage(directUrl, 45000);
    } catch (e1) {
      // The server route PIPES THE IMAGE BYTES through our own host, which is
      // precisely the load that is meant to stay on the visitor's device. It is
      // therefore local-dev only, matching the text path in pollinations.js —
      // and the server refuses it in production anyway (aiServerAllowed), so
      // attempting it there would only spend 60s to arrive at the same failure.
      if (!IS_LOCAL) throw e1;
      console.warn('[ai] direct image failed; local dev, trying the server route:', e1?.message || e1);
      setStatus('Still generating…');
      url = await preloadImage(serverUrl, 60000);
    }
    reply.imageUrl = url;
    reply.imageState = 'done';
  } catch (e2) {
    console.error('[ai] image generation failed:', e2?.message || e2);
    reply.imageState = 'error';
  }
  render();
  setStatus('Online AI ready · free & unlimited · try /image');
}

// Fully load an image URL into the browser cache before we show it, so the chat
// swaps from the spinner straight to the finished picture. Resolves with the URL
// once the bytes are decoded; rejects on error OR after timeoutMs (generation
// stuck / host blocked) so the caller can fall back.
function preloadImage(url, timeoutMs) {
  return new Promise((resolve, reject) => {
    const im = new Image();
    const finish = (fn, arg) => { clearTimeout(timer); im.onload = im.onerror = null; fn(arg); };
    const timer = setTimeout(() => { im.src = ''; finish(reject, new Error('timeout')); }, timeoutMs);
    im.onload  = () => (im.naturalWidth > 0 ? finish(resolve, url) : finish(reject, new Error('empty')));
    im.onerror = () => finish(reject, new Error('load-error'));
    im.src = url;
  });
}

// ===========================================================================
// Local in-browser model (Transformers.js) — only spun up when the network is
// blocked. Branding stays neutral; nothing about the library is shown.
// ===========================================================================
async function localGenerate(messages, reply) {
  const gen = await ensurePipeline();
  const { TextStreamer } = await import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.0.2/dist/transformers.min.js');
  let acc = '', streamed = false;
  const streamer = new TextStreamer(gen.tokenizer, {
    skip_prompt: true,
    callback_function: (text) => { streamed = true; acc += text; reply.content = acc; reply.streaming = false; render(); }
  });
  const out = await gen(messages, { max_new_tokens: 256, do_sample: true, temperature: 0.7, top_p: 0.95, streamer });
  if (!streamed) {
    const last = out?.[0]?.generated_text;
    reply.content = (Array.isArray(last) ? last[last.length - 1]?.content : String(last || '')) || '(no response)';
    reply.streaming = false; render();
  }
}

async function ensurePipeline() {
  if (pipelinePromise) return pipelinePromise;
  setStatus('Downloading local engine (one-time)…');
  pipelinePromise = (async () => {
    const { pipeline, env } = await import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.0.2/dist/transformers.min.js');
    env.allowLocalModels = false;
    env.useBrowserCache = true;
    const gen = await pipeline('text-generation', MODEL, {
      dtype: 'q4',
      device: (await detectWebGPU()) ? 'webgpu' : 'wasm',
      progress_callback: (p) => {
        if (p?.status === 'progress' && typeof p.progress === 'number') setStatus(`Loading model · ${p.progress.toFixed(0)}%`);
        else if (p?.status === 'ready') setStatus('Local engine ready');
      }
    });
    setStatus('Local engine ready');
    return gen;
  })();
  return pipelinePromise;
}

async function detectWebGPU() {
  try { return !!(navigator.gpu && (await navigator.gpu.requestAdapter())); }
  catch { return false; }
}

// ===========================================================================
// Chat state, history, rendering, composer (unchanged behavior)
// ===========================================================================
function newChat() {
  current = { id: `c_${Date.now().toString(36)}`, title: 'New chat', messages: [] };
  render();
  loadHistory();
  $('#aiInput')?.focus();
}

function loadHistory() {
  const wrap = $('#aiHistory'); if (!wrap) return;
  wrap.innerHTML = '';
  const chats = store.chats.list();
  const clearBtn = $('#aiClearAll');
  if (clearBtn) clearBtn.hidden = chats.length === 0;
  for (const c of chats) {
    const item = el('div', { class: `ai-history-item${current?.id === c.id ? ' active' : ''}`, title: c.title });
    const label = el('span', { class: 'ai-history-title' });
    label.textContent = c.title || 'Untitled';
    const del = el('button', { class: 'ai-history-del', type: 'button', title: 'Delete chat', 'aria-label': 'Delete chat' });
    del.innerHTML = '&times;';
    del.addEventListener('click', (e) => {
      e.stopPropagation();
      store.chats.remove(c.id);
      if (current && current.id === c.id) { current = null; render(); }
      loadHistory();
    });
    item.appendChild(label);
    item.appendChild(del);
    item.addEventListener('click', () => { current = c; render(); loadHistory(); });
    wrap.appendChild(item);
  }
}

function clearAllChats() {
  if (!store.chats.list().length) return;
  const ok = (typeof confirm === 'function') ? confirm('Delete all chats? This cannot be undone.') : true;
  if (!ok) return;
  store.chats.clear();
  current = null;
  render();
  loadHistory();
}

const WELCOME = `
  <div class="ai-welcome">
    <div class="ai-welcome-mark"></div>
    <h1>ZoFHub AI</h1>
    <p>Ask anything — homework help, brainstorming, writing, code. Free &amp; unlimited.</p>
    <div class="ai-suggest">
      <button class="ai-suggest-card" data-prompt="Explain photosynthesis like I'm 10."><b>Explain</b><span>Photosynthesis, but simple</span></button>
      <button class="ai-suggest-card" data-prompt="/image a neon space cat surfing a comet"><b>/image</b><span>Generate a picture</span></button>
      <button class="ai-suggest-card" data-prompt="Give me 5 fun game ideas to try on ZoFHub."><b>Ideas</b><span>What should I play?</span></button>
      <button class="ai-suggest-card" data-prompt="Write a JavaScript function that shuffles an array."><b>Code</b><span>Write some code</span></button>
    </div>
  </div>`;

function render() {
  const wrap = $('#aiMessages'); if (!wrap) return;
  if (!current || !current.messages.length) {
    wrap.innerHTML = WELCOME;
    bindSuggestCards(wrap);
    return;
  }
  wrap.innerHTML = '';
  current.messages.forEach(m => wrap.appendChild(messageRow(m)));
  wrap.scrollTop = wrap.scrollHeight;
}

function messageRow(m) {
  const row = el('div', { class: `msg ${m.role}` });
  let body;
  if (m.streaming) {
    body = '<span class="typing-dots"><span></span><span></span><span></span></span>';
  } else if (m.kind === 'image') {
    if (m.imageState === 'loading') {
      body = `<div class="ai-image-wrap">
          <div class="ai-image ai-image-loading"><span class="ai-spin" aria-hidden="true"></span><span class="ai-image-loadtxt">Generating…</span></div>
          <div class="ai-image-cap">${escapeHtml(m.content || '')}</div>
        </div>`;
    } else if (m.imageState === 'error' || !m.imageUrl) {
      body = `<div class="ai-image-err">That image didn’t generate — hit send again to retry.</div>`;
    } else {
      body = `<div class="ai-image-wrap">
          <img class="ai-image" src="${escapeHtml(m.imageUrl)}" alt="${escapeHtml(m.content || 'AI image')}" />
          <div class="ai-image-cap">${escapeHtml(m.content || '')}</div>
        </div>`;
    }
  } else {
    body = m.role === 'assistant' ? renderMarkdownLite(m.content) : escapeHtml(m.content);
  }
  row.innerHTML = `<div class="msg-av">${m.role === 'user' ? 'You' : 'AI'}</div><div class="msg-body">${body}</div>`;
  // Safety net: the image was already preloaded before we rendered it, but if the
  // browser evicted it from cache between preload and paint, show the error tile
  // (CSP-safe — inline onerror attributes are blocked by our CSP).
  row.querySelectorAll('img.ai-image').forEach(elm => {
    elm.addEventListener('error', () => {
      elm.closest('.ai-image-wrap')?.replaceWith(Object.assign(document.createElement('div'),
        { className: 'ai-image-err', textContent: 'Image failed to load — try again.' }));
    });
  });
  return row;
}

function bindComposer() {
  const form = $('#aiForm'); const input = $('#aiInput');
  if (!form || !input) return;
  input.addEventListener('input', () => autoSize(input));
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); form.requestSubmit(); }
  });
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const text = input.value.trim();
    if (!text || composing || aiCooling) return;
    if (!current) newChat();
    current.messages.push({ role: 'user', content: text });
    if (current.title === 'New chat') current.title = text.slice(0, 40);
    input.value = ''; autoSize(input);
    render();
    startSendCooldown();
    await respond();
  });
}

function autoSize(input) {
  input.style.height = 'auto';
  input.style.height = Math.min(180, input.scrollHeight) + 'px';
}

function finishTurn() {
  composing = false;
  setSendBusy(false);
  store.chats.save(current);
  loadHistory();
}

let aiCooling = false;
let aiCooldownTimer = null;
function setSendBusy(busy) {
  const b = $('#aiSend'); if (!b) return;
  const lock = busy || aiCooling;
  b.disabled = lock; b.style.opacity = lock ? .5 : 1;
  b.classList.toggle('is-cooldown', aiCooling);
}
// Light throttle: lock Send for 2.5s after each prompt. Each user now calls
// Pollinations on their OWN IP, so this only guards against accidental
// double-sends / rapid-fire tripping the user's own per-IP limit.
function startSendCooldown() {
  aiCooling = true;
  setSendBusy(true);
  clearTimeout(aiCooldownTimer);
  aiCooldownTimer = setTimeout(() => { aiCooling = false; setSendBusy(composing); }, 2500);
}
